from pathlib import Path
import joblib
import numpy as np
import pandas as pd
import torch
from torch import nn
from catboost import CatBoostRegressor

BASE = Path(__file__).resolve().parent


COLS = [
    "TOL_31.6",
    "TOL_39.8",
    "TOL_50.1",
    "TOL_63.1",
    "TOL_79.4",
    "TOL_100",
    "TOL_125.9",
    "TOL_158.5",
    "TOL_199.5",
    "TOL_251.2",
    "TOL_316.2",
    "TOL_398.1",
    "TOL_501.2",
    "TOL_631",
    "TOL_794.3",
    "TOL_1000",
    "TOL_1258.9",
    "TOL_1584.9",
    "TOL_1995.3",
    "TOL_2511.9",
    "TOL_3162.3",
    "TOL_3981.1",
    "TOL_5011.9",
    "TOL_6309.6",
    "TOL_7943.3",
]


def energy(db):
    """Scale each window safely; NaN remains unobserved (zero only in sums)."""
    maximum = np.nanmax(db, axis=(1, 2), keepdims=True)
    maximum = np.where(np.isfinite(maximum), maximum, 0)
    e = np.where(np.isfinite(db), np.power(10.0, (db - maximum) / 10), 0).astype(np.float32)
    return e, maximum


def feature_batch(db, templates=None):
    db = np.asarray(db, dtype=np.float32)
    mask = np.isfinite(db)
    n = len(db)
    cols = []
    names = []

    def add(x, name):
        x = np.asarray(x).reshape(n, -1)
        cols.append(x)
        names.extend([name] if x.shape[1] == 1 else [f"{name}_{j:02d}" for j in range(x.shape[1])])

    with warnings.catch_warnings():
        warnings.simplefilter("ignore", RuntimeWarning)
        mean = np.nanmean(db, 1)
        std = np.nanstd(db, 1)
        q = np.nanpercentile(db, [10, 25, 50, 75, 90], axis=1)
        fullmean = np.nanmean(db, axis=(1, 2))
        fullstd = np.nanstd(db, axis=(1, 2))
        e, offset = energy(db)
        count = mask.sum((1, 2))
        total = e.sum((1, 2)) + 1e-25
        totals_db = 10 * np.log10(total / np.maximum(count, 1)) + offset[:, 0, 0]
        band_count = mask.sum(1)
        band_e = e.sum(1) / np.maximum(band_count, 1)
        band_db = 10 * np.log10(np.maximum(band_e, 1e-25)) + offset[:, 0, :]
        add(fullmean, "global_mean")
        add(fullstd, "global_std")
        add(totals_db, "received_energy_db")
        add(mask.mean((1, 2)), "coverage")
        add(mask.mean(1), "band_coverage")
        add(mask.mean(2), "minute_coverage")
        add(mean, "band_mean")
        add(std, "band_std")
        add(q[2], "band_median")
        add(q[4] - q[0], "band_range90_10")
        add(q[3] - q[1], "band_iqr")
        add(mean - fullmean[:, None], "relative_spectrum")
        add(band_db, "band_energy_db")
        add(band_db - mean, "energy_arithmetic_excess")
        add(np.diff(mean, axis=1), "spectral_difference")
        add(np.diff(mean, n=2, axis=1), "spectral_curvature")
        band_frac = e.sum(1) / total[:, None]
        add(band_frac, "band_energy_fraction")
        delta = np.diff(db, axis=1)
        add(np.nanmean(np.abs(delta), 1), "time_mean_abs_difference")
        add(np.nanstd(delta, 1), "time_std_difference")
        add(np.nanmean(np.abs(np.diff(db, n=2, axis=1)), 1), "time_second_difference")
        # Temporal summaries over broad frequency ranges.
        for lo, hi in [(0, 25), (0, 8), (8, 17), (17, 25), (0, 4), (4, 12), (12, 21)]:
            name = f"group{lo}_{hi}"
            eg = e[:, :, lo:hi]
            mg = mask[:, :, lo:hi]
            trajectory = eg.sum(2) / np.maximum(mg.sum(2), 1)
            trajectory = np.where(mg.any(2), trajectory, np.nan)
            level = 10 * np.log10(np.maximum(trajectory, 1e-25)) + offset[:, 0, :]
            center = np.nanmean(level, 1, keepdims=True)
            add(np.nanmean(db[:, :, lo:hi], (1, 2)), name + "_db")
            add(eg.sum((1, 2)) / total, name + "_share")
            add(np.nanstd(level, 1), name + "_std")
            add(np.nanmax(level, 1) - np.nanmin(level, 1), name + "_range")
            add(np.nanmean(np.abs(np.diff(level, axis=1)), 1), name + "_roughness")
            rel = np.nan_to_num(level - center, nan=0.0)
            add(np.sum(rel[:, :-1] * rel[:, 1:], 1) / (np.sum(rel * rel, 1) + 1e-6), name + "_lag1")
            add(np.sum(rel[:, :-2] * rel[:, 2:], 1) / (np.sum(rel * rel, 1) + 1e-6), name + "_lag2")
            add(
                np.nanmean(level[:, :5], 1) - np.nanmean(level[:, -5:], 1),
                name + "_edge_difference",
            )
            add(
                np.nanmean(level[:, 5:10], 1)
                - 0.5 * (np.nanmean(level[:, :5], 1) + np.nanmean(level[:, -5:], 1)),
                name + "_center_bulge",
            )
            baseline = np.nanpercentile(trajectory, 20, axis=1)
            add(
                np.nansum(np.maximum(trajectory - baseline[:, None], 0), 1)
                / (np.nansum(trajectory, 1) + 1e-25),
                name + "_temporal_excess",
            )
            add(
                np.nanmax(trajectory, 1) / (np.nansum(trajectory, 1) + 1e-25),
                name + "_peak_fraction",
            )
            if lo in [0, 8, 17] and hi in [25, 17]:
                add(rel, name + "_trajectory")
        # Coherent changes across bands, without relying on sub-dB export rounding.
        centered = np.nan_to_num(db - mean[:, None, :], nan=0.0)
        singular = np.linalg.svd(centered, compute_uv=False)
        ev = singular**2
        ev /= ev.sum(1, keepdims=True) + 1e-8
        add(ev[:, :5], "temporal_singular_energy")
        add(-np.sum(band_frac * np.log(np.maximum(band_frac, 1e-25)), 1), "spectral_entropy")
        add(np.sort(band_frac, axis=1)[:, -5:], "largest_band_shares")
        if templates is not None:
            # Broad clustered spectral shapes, never a nearest-recording lookup.
            diff = mean[:, None, :] - templates[None, :, :]
            shift = np.nanmedian(diff, axis=2)
            resid = diff - shift[:, :, None]
            errors = np.nanmean(np.minimum(resid**2, 100), axis=2)
            best = np.argsort(errors, axis=1)[:, :3]
            for k in range(3):
                index = best[:, k]
                template = templates[index]
                difference = band_db - template
                lower_shift = np.nanpercentile(
                    np.where(band_count > 0, difference, np.nan), 20, axis=1
                )
                base = np.power(
                    10.0, np.clip((template + lower_shift[:, None] - offset[:, 0, :]) / 10, -25, 10)
                )
                excess = np.maximum(band_e - base, 0) * band_count
                add(excess.sum(1) / total, f"template{k}_excess")
                add(errors[np.arange(n), index], f"template{k}_error")
            add(resid[np.arange(n), best[:, 0]], "template_residual")
    features = np.concatenate(cols, axis=1).astype(np.float32)
    features[~np.isfinite(features)] = np.nan
    return features, names


def features(db, templates=None, batch_size=1024):
    result = []
    names = None
    for i in range(0, len(db), batch_size):
        f, names = feature_batch(db[i : i + batch_size], templates)
        result.append(f)
    return np.concatenate(result), names


class AcousticNet(nn.Module):
    def __init__(self, n_features):
        super().__init__()
        self.feature_net = nn.Sequential(
            nn.Linear(n_features, 256),
            nn.LayerNorm(256),
            nn.SiLU(),
            nn.Dropout(0.08),
            nn.Linear(256, 128),
            nn.SiLU(),
        )
        self.conv = nn.Sequential(
            nn.Conv2d(4, 32, 3, padding=1),
            nn.GroupNorm(8, 32),
            nn.SiLU(),
            nn.Conv2d(32, 48, 3, padding=2, dilation=2),
            nn.GroupNorm(8, 48),
            nn.SiLU(),
            nn.Conv2d(48, 64, 3, padding=3, dilation=3),
            nn.GroupNorm(8, 64),
            nn.SiLU(),
        )
        self.pool = nn.AdaptiveAvgPool2d((3, 5))
        self.head = nn.Sequential(
            nn.Linear(128 + 64 * 15, 256),
            nn.SiLU(),
            nn.Dropout(0.08),
            nn.Linear(256, 64),
            nn.SiLU(),
            nn.Linear(64, 2),
        )
        self.cell_head = nn.Sequential(nn.Conv2d(64, 16, 1), nn.SiLU(), nn.Conv2d(16, 1, 1))

    def forward(self, raw, feat, weights):
        hidden = self.conv(raw)
        logits = self.head(torch.cat([self.feature_net(feat), self.pool(hidden).flatten(1)], dim=1))
        cell = torch.sigmoid(self.cell_head(hidden)).squeeze(1)
        physical = (cell * weights).sum((1, 2))
        global_share = torch.sigmoid(logits[:, 0])
        return 0.5 * (physical + global_share), logits[:, 1], cell, physical, global_share


def raw_inputs(db):
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", RuntimeWarning)
        avg = np.nanmean(db, (1, 2), keepdims=True)
        band = np.nanmean(db, 1, keepdims=True)
        raw = np.stack(
            [(db - 80) / 35, (db - avg) / 20, (db - band) / 10, np.isfinite(db).astype(np.float32)],
            1,
        )
    raw = np.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).astype(np.float32)
    e, _ = energy(db)
    weights = e / (e.sum((1, 2), keepdims=True) + 1e-25)
    return raw, weights


def neural_predict(model, db, feat, normalizer, device="cpu", batch_size=256):
    result = []
    evidence = []
    physical = []
    global_share = []
    model.eval()
    for i in range(0, len(db), batch_size):
        raw, weight = raw_inputs(db[i : i + batch_size])
        f = np.nan_to_num(
            (feat[i : i + batch_size] - normalizer["mean"]) / normalizer["std"], nan=0.0
        )
        with torch.no_grad():
            outputs = model(
                torch.as_tensor(raw, device=device),
                torch.as_tensor(np.clip(f, -10, 10), device=device),
                torch.as_tensor(weight, device=device),
            )
        result.append(outputs[0].cpu().numpy())
        evidence.append(torch.sigmoid(outputs[1]).cpu().numpy())
        physical.append(outputs[3].cpu().numpy())
        global_share.append(outputs[4].cpu().numpy())
    return (
        np.concatenate(result),
        np.concatenate(evidence),
        np.concatenate(physical),
        np.concatenate(global_share),
    )


class Ensemble:
    def __init__(self, tree_dir, neural_dir, device="cpu"):
        self.tree_dir = BASE / "runs" / tree_dir
        self.neural_dir = BASE / "runs" / neural_dir
        self.templates = np.load(self.tree_dir / "templates.npy")
        self.models = {
            k: joblib.load(self.tree_dir / (k + ".joblib"))
            for k in ["lightgbm", "conservative", "evidence"]
        }
        self.cat = CatBoostRegressor()
        self.cat.load_model(str(self.tree_dir / "catboost.cbm"))
        ck = torch.load(self.neural_dir / "model.pt", map_location="cpu", weights_only=True)
        self.neural = AcousticNet(ck["n_features"]).to(device)
        self.neural.load_state_dict(ck["state_dict"])
        self.device = device
        self.normalizer = dict(np.load(self.neural_dir / "normalizer.npz"))
        np.testing.assert_array_equal(self.templates, np.load(self.neural_dir / "templates.npy"))

    def predict_components(self, db):
        x, names = features(db, self.templates)
        a = np.clip(self.models["lightgbm"].predict(x), 0, 1)
        b = np.clip(self.cat.predict(np.nan_to_num(x, nan=-9999.0)), 0, 1)
        c = np.clip(self.models["conservative"].predict(x), 0, 1)
        d, nev, _, _ = neural_predict(self.neural, db, x, self.normalizer, self.device)
        ev = self.models["evidence"].predict_proba(x)[:, 1]
        base = np.column_stack([a, b, c, d])
        return np.column_stack([base, base * ev[:, None]]), ev, nev


def sha256(path):
    h = hashlib.sha256()
    with Path(path).open("rb") as f:
        for block in iter(lambda: f.read(2**20), b""):
            h.update(block)
    return h.hexdigest()


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--test", type=Path, default=BASE.parent / "Test.csv")
    p.add_argument("--sample", type=Path, default=BASE.parent / "sample_submission.csv")
    p.add_argument("--output", type=Path, default=BASE.parent / "submission.csv")
    p.add_argument("--alternative", type=Path, default=BASE.parent / "submission_conservative.csv")
    p.add_argument("--tree", default="final")
    p.add_argument("--neural", default="neural_final")
    p.add_argument("--selection", type=Path, default=BASE / "reports/frozen_selection.json")
    p.add_argument("--device", default="cpu")
    p.add_argument("--expected-rows", type=int, default=1500)
    args = p.parse_args()
    started = time.time()
    torch.set_num_threads(5)
    spec = json.loads(args.selection.read_text())
    assert spec["test_inputs_read"] is False and spec["audit_used_for_selection"] is False
    # Validate the frozen model list before opening competition acoustic inputs.
    model = Ensemble(args.tree, args.neural, args.device)
    summary = json.loads((BASE / "runs" / args.tree / "training_summary.json").read_text())
    feature_cols = [f"m{m:02d}_{c}" for m in range(1, 16) for c in COLS]
    test = pd.read_csv(args.test, dtype={"ID": str})
    sample = pd.read_csv(args.sample, dtype={"ID": str})
    required = ["ID", "share_added_vessel", "score_added_vessel"]
    assert test.columns.tolist() == ["ID"] + feature_cols
    assert sample.columns.tolist() == required
    assert len(test) == len(sample) == args.expected_rows
    assert (
        test.ID.is_unique
        and sample.ID.is_unique
        and test.ID.notna().all()
        and sample.ID.notna().all()
    )
    assert set(test.ID) == set(sample.ID)
    values = test[feature_cols].to_numpy(np.float32).reshape(-1, 15, 25)
    assert not np.isinf(values).any(), "Only finite values or missing NaN cells are valid inputs."
    observed = np.isfinite(values).any((1, 2))
    component = np.full((len(test), len(spec["component_order"])), summary["target_mean"])
    component[:, 2] = summary["conservative_target_mean"]
    evidence = np.full(len(test), summary["addition_rate"])
    if observed.any():
        component[observed], evidence[observed], _ = model.predict_components(values[observed])
    primary = np.clip(component @ np.asarray(spec["weights"]), 0, 1)
    alternative = np.clip(component @ np.asarray(spec["conservative_weights"]), 0, 1)
    primary[~observed] = summary["target_mean"]
    alternative[~observed] = summary["conservative_target_mean"]
    evidence = np.clip(evidence, 0, 1)
    records = {}
    for path, prediction in [(args.output, primary), (args.alternative, alternative)]:
        frame = (
            pd.DataFrame(
                {"ID": test.ID, "share_added_vessel": prediction, "score_added_vessel": evidence}
            )
            .set_index("ID")
            .loc[sample.ID]
            .reset_index()
        )
        assert frame.columns.tolist() == required and frame.ID.equals(sample.ID)
        arr = frame[required[1:]].to_numpy()
        assert np.isfinite(arr).all() and ((arr >= 0) & (arr <= 1)).all()
        path.parent.mkdir(parents=True, exist_ok=True)
        frame.to_csv(path, index=False, float_format="%.17g")
        saved = pd.read_csv(path, dtype={"ID": str})
        assert saved.ID.equals(sample.ID) and len(saved) == args.expected_rows
        assert np.isfinite(saved[required[1:]].to_numpy()).all()
        records[path.name] = {"rows": len(saved), "sha256": sha256(path)}
        print("Saved and validated", path, flush=True)
    models = {
        str(p.relative_to(BASE)): sha256(p)
        for directory in [model.tree_dir, model.neural_dir]
        for p in directory.iterdir()
        if p.suffix in [".joblib", ".cbm", ".pt", ".npy", ".npz"]
    }
    report = {
        "test_sha256": sha256(args.test),
        "sample_sha256": sha256(args.sample),
        "selection_sha256": sha256(args.selection),
        "models": models,
        "outputs": records,
        "wall_seconds": time.time() - started,
        "peak_rss_mb": resource.getrusage(resource.RUSAGE_SELF).ru_maxrss / 2**20,
        "device": args.device,
        "test_used_for": "inference only; no fitting, selection, calibration, or training examples",
        "empty_window_fallback": "Training augmentation mean / addition rate; fixed before reading test.",
    }
    (args.output.parent / (args.output.stem + "_inference_report.json")).write_text(
        json.dumps(report, indent=2)
    )
    print(
        json.dumps(
            {
                "inference_seconds": report["wall_seconds"],
                "peak_memory_mb": report["peak_rss_mb"],
                "output_rows": len(test),
            }
        ),
        flush=True,
    )


if __name__ == "__main__":
    main()
